SELECT * FROM (SELECT CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END AS txn_cohort, AVG(amount) AS avg_amount, COUNT(amount) AS amount_count FROM transactions WHERE merchant = 'Starbucks' GROUP BY CASE WHEN YEAR(txn_time) < 2024 THEN 'before_2024' WHEN YEAR(txn_time) = 2024 THEN '2024' ELSE 'after_2024' END) AS agg WHERE avg_amount < 1100
